import{_ as t,o as s,c as r,ag as e}from"./chunks/framework.C9sp7nFj.js";const C=JSON.parse('{"title":"CalcCoord 计算用户坐标系","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/CalcCoord.md","filePath":"3. 指令/5. 设置指令/CalcCoord.md","lastUpdated":1778862643000}'),o={name:"3. 指令/5. 设置指令/CalcCoord.md"};function n(d,a,i,l,h,c){return s(),r("div",null,[...a[0]||(a[0]=[e(`<h1 id="calccoord-计算用户坐标系" tabindex="-1">CalcCoord 计算用户坐标系 <a class="header-anchor" href="#calccoord-计算用户坐标系" aria-label="Permalink to &quot;CalcCoord 计算用户坐标系&quot;">​</a></h1><p>该指令用于<strong>通过&quot;三点法&quot;自动计算机器人的用户坐标系（User Coordinate System）</strong>。当工件倾斜摆放或工作台不在机器人基坐标系的轴向上时，通过定义原点、X 轴方向和 XY 平面，可以建立一个新的坐标基准，使编程时的运动方向与工件表面完全对齐。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>CalcCoord(P1, P2, P3, Coord) CalcCoord(原点, X轴指向点, XY平面点, 用户坐标系变量)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>P1：原点（Original Position）</td><td>CPOS</td><td>定义新坐标系的零点位置 (0, 0, 0)。</td><td></td></tr><tr><td>P2：RX 方向标定点</td><td>CPOS</td><td>从原点指向该点的矢量被定义为新坐标系的 <strong>+X 轴</strong>方向。</td><td></td></tr><tr><td>P3：RXRY 平面标定点</td><td>CPOS</td><td>该点与 P1、P2 共同确定一个新的平坦面（XY 平面）。系统会根据右手定则自动推算出 <strong>+Y 轴</strong>和 <strong>+Z 轴</strong>的方向。</td><td></td></tr><tr><td>Coord：用户参数（UserCoord Param）</td><td>USERCOORD 变量</td><td>存储计算结果的容器。计算出的坐标系偏移和旋转数据将写入此变量（如 <code>USERCOORD1</code>）。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>三点法利用几何约束确定一个局部空间直角坐标系。P1 确定位置，P1-P2 确定 X 轴线，P3 确定平面的倾斜度。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// P1 为工作台左下角，P2 为右下角，P3 为左上角</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CalcCoord</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, P2, P3, USERCOORD1)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 启用该坐标系</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetCoord</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(USERCOORD1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>执行结果：</strong></p><p>系统生成一个新的坐标系 <strong>USERCOORD1</strong>。此时，如果执行 <code>MovL</code> 并增加 X 值，机器人将沿着工作台的长边移动，而不再是沿着机器人的基座轴向移动。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>倾斜工装适配</strong>：当传送带或治具与机器人底座不平行时，建立用户坐标系可让直线运动与治具边缘平行。</li><li><strong>多工位快速切换</strong>：在同一个工作区有多个相同的工件，只需为每个工件标定一个 <code>USERCOORD</code>，即可复用同一套加工轨迹。</li><li><strong>离线编程对位</strong>：将离线软件生成的理论坐标系与现场实际工件的位置进行匹配校准。</li></ul>`,18)])])}const u=t(o,[["render",n]]);export{C as __pageData,u as default};
